/**
 * @method
 * @name dts_Receiver_OnLoadCompleted
 * @description dts_Receiver 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Receiver_OnLoadCompleted = function(rowcount) {
    try {
        txb_receiver_cnt.setValue("(총 : " + rowcount + " 건)");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30313.dts_Receiver_OnLoadCompleted" });
    }
};

