};

/**
 * @method
 * @name dts_attach_file_OnLoadCompleted
 * @description dts_attach_file 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_attach_file_OnLoadCompleted = function(rowcount) {
    try {
        gImprRegDd = dts_attach_file.getCellData(1, "IMPR_REG_DD");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30313.dts_attach_file_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name grd_fileList_OnDblClick
 * @description grd_fileList 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_fileList_OnDblClick = function(row, colid) {
    try {
        if (dts_fileData.getRowStatus(dts_fileData.getRowPosition()) === 0) {
            scwin.filedown(dts_fileData.getCellData(row, "NOTI_SVC_ID"), dts_fileData.getCellData(row, "FILE_SEQ"));
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30313.grd_fileList_OnDblClick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name read
 * @description read 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.read = async function() {
    // alert(url);
    const sbmOptions = {
        id : "sbm_dts_Master",
        action : "/EmailMgt.do",
        ref : "",
        target : "dts_Master=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // alert(url);
    const sbmOptions2 = {
        id : "sbm_dts_fileData",
        action : "/EmailMgt.do",
        ref : "",
        target : "dts_fileData=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions3 = {
        id : "sbm_dts_Receiver",
        action : "/EmailMgt.do",
        ref : "",
        target : "dts_Receiver=body.content",
        isProcessMsg : false
    };

    const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
    // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {void}
 * @hidden N
 */
scwin.setCode = function() {

};

/**
 * @method
 * @name initPage
 * @description init Page 처리
 * @returns {void}
 * @hidden N
 */
scwin.initPage = function() {
    scwin.gNOTI_SVC_ID = $c.stf.getQuery(frame.srcUrl, "NOTI_SVC_ID");
};

/**
 * @method
 * @name filedown
 * @description 첨부파일 다운로드
 * @param {String} vNotiSvcId vNotiSvcId
 * @param {*} vSeq vSeq
 * @returns {void}
 * @hidden N
 */
scwin.filedown = function(vNotiSvcId, vSeq) {
    // var vNotiSvcId= getObjectValue(txb_NOTI_SVC_ID);
    // var vSeq= getObjectValue(txb_file_seq);

    const link = "/filedownload.do?NOTI_SVC_ID=" + vNotiSvcId + "&SEQ=" + vSeq + "&gubun=11";
    location.href = encodeURI(link);
};

/**
 * @method
 * @name hideDebugCtrls
 * @description hide Debug Ctrls 처리
 * @returns {void}
 * @hidden N
 */
scwin.hideDebugCtrls = function() {
    panel_debug.hide();
};

/**
 * @method
 * @name setContnId
 * @description 그리드에서 클릭 row의 변수셋팅
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setContnId = function(obj) {
    scwin.gIsurCd = dts_Receiver.getCellData(Number(obj), "ISUR_CD");
    // alert("부모창:"+ gIsurCd);

};

/**
 * @method
 * @name grd_fileList_CanColumnPosChange
 * @description grd file List Can Column Pos Change 처리
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_fileList_CanColumnPosChange = function(row, colid) {
    return true;
};
